def copy_rest_ready(rested_at, now):
    """True after the pointer has rested on the copy button for 250 ms."""
    return rested_at is not None and now - rested_at >= COPY_REST_S


def copy_wheel_captured(rested_at, now, tag_shown=False, keyboard_focus=False):
    """The kind switch takes the wheel only after that rest, or while the tag shows."""
    return bool(keyboard_focus or tag_shown or copy_rest_ready(rested_at, now))


def copy_wheel_step(state, delta, now, surface=False):
    """(step, state): +1/-1 for one kind step. A wheel notch steps once; smooth deltas accumulate to one step."""
    if not delta:
        return 0, state
    state = dict(state)
    if not surface:
        # One wheel notch is 1.0. Hi-res wheels send fractions that add up to one notch; a large event is still one step.
        if now - state["ts"] > .2:
            state["acc"] = 0.0
        state["ts"] = now
        if state["acc"] and (state["acc"] > 0) != (delta > 0):
            state["acc"] = 0.0
        state["acc"] += delta
        if abs(state["acc"]) < 1.0:
            return 0, state
        step = 1 if state["acc"] > 0 else -1
        state["acc"] -= step
        if abs(delta) >= 1.0 or abs(state["acc"]) >= 1.0:
            state["acc"] = 0.0
        return step, state
    # A trackpad: one step per burst of smooth deltas.
    if now - state["ts"] > .12:
        state["acc"] = 0.0
        state["armed"] = True
    state["ts"] = now
    if not state["armed"]:
        return 0, state
    state["acc"] += delta
    if abs(state["acc"]) < 30:
        return 0, state
    state["armed"] = False
    return (1 if state["acc"] > 0 else -1), {**state, "acc": 0.0}


def popover_shift(anchor_x, anchor_width, popover_width, window_width, margin=8):
    left = anchor_x + (anchor_width - popover_width) / 2
    if popover_width > window_width - 2 * margin:
        return round(margin - left)
    return round(min(max(left, margin), window_width - margin - popover_width) - left)


def popover_press_inside(gesture, x, y, window, popover):
    """True when a press at (x, y) in window coordinates belongs to the popover: it came on the popover's own surface, or it is
    inside the visible body (the `contents` node; the shadow margin around it is outside), or the popover has no layout yet.
    A press on the window surface that belongs to the popover is claimed, so no widget under it gets it."""
    event = gesture.get_current_event()
    surface = event.get_surface() if event is not None else None
    if popover.get_width() and surface != popover.get_surface():
        body = popover.get_first_child()
        while body is not None and body.get_css_name() != "contents":
            body = body.get_next_sibling()
        found, bounds = (body or popover).compute_bounds(window)
        if not found or not bounds.contains_point(Graphene.Point().init(x, y)):
            return False
    # Before the popup surface maps, a press in its place must not reach a widget under it.
    if surface is not None and surface == window.get_surface():
        gesture.set_state(Gtk.EventSequenceState.CLAIMED)
    return True


def popover_outside_press(gesture, _count, x, y, window, popover, anchor):
    if not popover.get_visible():
        return
    event = gesture.get_current_event()
    # After a widget under a still pointer hides, GTK 4 picks the new pointer target on the window with the popover's
    # surface coordinates, so the next press goes to a board widget; it belongs to the popover.
    if getattr(popover, "asb_misrouted", False) and event is not None and event.get_surface() == popover.get_surface():
        gesture.set_state(Gtk.EventSequenceState.CLAIMED)
        if hasattr(window, "panel_forward_press") and hasattr(popover, "asb_identity"):
            window.panel_forward_press(popover, *window.panel_event_point(popover, event))
        return
    point = Graphene.Point().init(x, y)
    if isinstance(anchor, (Gtk.MenuButton, Gtk.DropDown, Adw.ComboRow)):
        found, bounds = anchor.compute_bounds(window)
        if found and bounds.contains_point(point):
            return
    if popover_press_inside(gesture, x, y, window, popover):
        return
    popover.popdown()


def non_autohide_popover(window, popover, anchor):
    """Close without an X11 grab, so another app gets its focus and keys."""
    popover.set_autohide(False)
    popover.connect("map", lambda popup: popup.child_focus(Gtk.DirectionType.TAB_FORWARD))
    if isinstance(anchor, Gtk.MenuButton):
        anchor.set_focus_on_click(False)
    def focus_left(controller):
        popup = controller.get_widget()
        def check():
            focus = window.get_focus()
            if popup.get_visible() and (focus is None or not focus.is_ancestor(popup)):
                popup.popdown()
            return False
        # Arrow-key wrapping can leave and re-enter the panel in the same event.
        GLib.idle_add(check)
    focus = Gtk.EventControllerFocus()
    focus.connect("leave", focus_left)
    popover.add_controller(focus)
    press = Gtk.GestureClick(button=0, propagation_phase=Gtk.PropagationPhase.CAPTURE)
    press_handler = press.connect("pressed", popover_outside_press, window, popover, anchor)
    release_handler = press.connect("released", lambda gesture, *_args: window.panel_forward_release(
        popover, *window.panel_event_point(popover, gesture.get_current_event())) if getattr(popover, "asb_forward", None) else None)
    window.add_controller(press)
    handlers = [window.connect("notify::is-active", lambda owner, _param: popover.popdown() if not owner.is_active() else None),
                window.connect("unmap", lambda *_: popover.popdown()),
                window.connect("close-request", lambda *_: popover.popdown() or False)]

    def unparented(popup, _param):
        if popup.get_parent() is None:
            for handler in handlers:
                window.disconnect(handler)
            window.remove_controller(press)
            press.disconnect(press_handler)
            press.disconnect(release_handler)
    # Row panels are short lived; do not keep them through the window's handlers.
    popover.connect("notify::parent", unparented)


def non_autohide_choice(window, choice):
    """Keep the native choice widget and configure its internal popover."""
    def configure(widget):
        child = widget.get_first_child()
        while child is not None:
            if isinstance(child, Gtk.Popover):
                non_autohide_popover(window, child, choice)
            else:
                configure(child)
            child = child.get_next_sibling()
    configure(choice)


def close_popovers_when_inactive(window, close):
    """Run close when window stays inactive. On X11 a popover is its own window: it would stay over the app that the user switched to."""
    if window.is_active() or getattr(window, "inactive_timer", None):
        return

    def check():
        window.inactive_timer = None
        # A popover that takes the grab makes its window inactive for a moment.
        if not window.closed and not window.is_active():
            close()
        return False
    window.inactive_timer = GLib.timeout_add(INACTIVE_POPOVER_MS, check)


def panel_place(x, y, width, height, window_width, window_height, margin=6):
    """Where a panel of this size, centered on x, points and opens ("bottom" or "top") to stay inside the window."""
    half = width / 2
    x = min(max(x, margin + half), window_width - margin - half) if window_width >= width + 2 * margin else window_width / 2
    if window_height - margin - y >= height or window_height - y >= y:
        return round(x), round(max(margin, min(y, window_height - margin - height))), "bottom"
    return round(x), round(min(window_height - margin, max(y, margin + height))), "top"


def edge_color(base, color, fraction, surfaces):
    """The weakest mix of color into base, from fraction up, with 3:1 contrast on each surface."""
    for percent in range(round(fraction * 100), 101):
        value = mix_color(base, color, percent / 100)
        if all(contrast(value, surface) >= 3 for surface in surfaces):
            return value
    return color


def pin_move_body(rows, identity, direction):
    """Return the move-pin body for the visible pinned neighbor, or None at the end of the visible pins."""
    pins = [row["id"] for row in rows if row.get("pinned")]
    target = pins.index(identity) + (-1 if direction == "up" else 1) if identity in pins else -1
    return {"targetId": pins[target], "placement": "before" if direction == "up" else "after"} if 0 <= target < len(pins) else None


def pin_moves(rows, identity):
    """(earlier, later): whether each pin move has a visible neighbor; None when the row is the only visible pin."""
    pins = [row["id"] for row in rows if row.get("pinned")]
    if identity not in pins or len(pins) < 2:
        return None
    index = pins.index(identity)
    return index > 0, index < len(pins) - 1


def panel_copy_values(row):
    """copy_values for the row panel: a remote row cannot copy a relative reference, so row 1 shows why."""
    values = copy_values(row)
    return (None, copy_relative_reason(row), *values[2:]) if row.get("remote") is True else values


# The remote relative row uses plain caption and description text; its tooltip keeps the full reason.
REMOTE_RELATIVE_CAPTION = "Only for a session on this machine."
PIN_MOVE_ENDS = {"pin-up": "Already the first pin", "pin-down": "Already the last pin"}
PANEL_MUTE_TIP = "Click the time to choose it. Scroll or press Left and Right to change it."
PANEL_MUTE_KEYS = "Left or Right changes the time."
PANEL_GONE_TEXT = "Not available now."
CARD_ACTION_KEYS = {"read": "Alt+R", "drawer": "Alt+D", "mute": "Alt+M", "pin": "Alt+P", "copy": "Alt+C", "discard": "Alt+W"}
# Every label that a row panel slot can show while the panel is open; the panel width fits the longest at open.
PANEL_SLOT_LABELS = {"read": ("Mark read", "Mark unread"), "mute": ("Mute", "Unmute"), "pin": ("Pin", "Unpin"),
                     "drawer": ("Put in drawer", "Take out of drawer"),
                     "discard": ("Mark read when done", "Leave unread when done", "Mark next result read", "Leave next result unread")}


def attention_signature(row):
    return tuple(row.get(key) for key in ("unread", "alert", "questionAttention", "nativeUnread", "manualUnread",
                 "nativeAttention", "completionAttention", "failedAttention", "retainedUnread", "retainedUnreadSource",
                 "completionAtMs", "failedAtMs", "lastOutcome", "actionRequired", "actionAttention", "discardResult", "updatedAtMs", "state", "workingSinceMs", "questionPending", "drawer", "muted"))


def shows_action(row):
    """A required action shows its "?" mark; on a muted or drawer row, only a request that came after the start of the mute
    or after the row went in the drawer (the engine then takes the row out of the drawer)."""
    return bool(row.get("actionRequired")) and (not (row.get("muted") or row.get("drawer")) or bool(row.get("actionAttention")))


def drawer_offer(row):
    """Put in drawer applies to a row with an unread dot or "!", and to a row that waits for an answer ("?")."""
    return not row.get("drawer") and (attention_indicator(row) in ("dot", "alert")
                                      or row.get("state") == "waiting" and attention_indicator(row) == "question")


def attention_indicator(row, drawer=False):
    """Return the row mark in question, alert, unread, discard, then stopped order. With drawer, a drawer row shows its stored unread mark.
    A usage-limit stop shows the stop square only after the reset, not during the countdown."""
    return "question" if shows_action(row) or row.get("questionAttention") \
        or drawer and row.get("drawer") and row.get("state") == "waiting" else "alert" if row.get("alert") else "dot" \
        if row.get("unread") or (drawer and row.get("drawer") and row.get("state") != "working" and not limit_left(row)) \
        else "discard" if row.get("state") in ("working", "idle") and row.get("discardResult") \
        else "stop" if row.get("state") == "idle" and (row.get("lastOutcome") == "stopped" or row.get("lastOutcome") == "limit" and not limit_left(row)) else ""


def question_wait_note(row):
    """The second sentence of the card "?" button and of the panel Mark read row, while the row has an unread "?"."""
    if attention_indicator(row, True) != "question":
        return ""
    if row.get("drawer") and row.get("state") == "waiting":
        return "The session still waits for your permission." if row.get("actionRequired") else "The session still waits for your answer."
    if not shows_action(row):
        return "The session still waits for your answer."
    return "The session still waits for your permission." if row.get("actionAttention") or row.get("unread") else ""


def quiet_card(row):
    return not (row.get("unread") or row.get("questionAttention") or row.get("pending")) and (
        row.get("state") in ("idle", "waiting") or row.get("state") == "unknown" and not attention_indicator(row, True))


def state_word(row):
    """The card state word. An Idle row says Failed after a failed task, and Stopped after a user stop or a usage limit stop,
    until the next task starts, also after Read. Filters and sorting keep the state names."""
    state = row.get("state", "unknown")
    state = state if state in STATES else "unknown"
    if state == "idle" and row.get("lastOutcome") == "failed":
        return "Failed"
    if state == "idle" and row.get("lastOutcome") in ("stopped", "limit"):
        return "Stopped"
    return state.capitalize()


def ignore_discard_after_read(action, last_read_at, now=None):
    now = time.monotonic() if now is None else now
    return action in ("discard-result", "keep-result") and last_read_at is not None and now - last_read_at < .5


def provider_query(query, app="all"):
    match = re.match(r"^\s*(cl|claude|cx|codex|oc|opencode)\s*:\s*(.*)$", query, re.IGNORECASE | re.DOTALL)
    if match:
        app = {"cl": "claude-desktop-code", "claude": "claude-desktop-code", "cx": "codex",
               "codex": "codex", "oc": "opencode", "opencode": "opencode"}[match[1].lower()]
        query = match[2]
    return query.strip().casefold(), app


# App order in the Filters popover and in profile chips: Codex, Claude, OpenCode.
APP_ORDER = ("codex", "claude-desktop-code", "opencode")


def order_of(provider):
    return APP_ORDER.index(provider) if provider in APP_ORDER else len(APP_ORDER)


def profile_key(machine, source_id):
    return f"{machine}|{source_id}"


def row_profile_key(row):
    """A row is in the profile (machine, sourceId): remote rows use their machineId, local rows are this machine."""
    machine = str(row.get("machineId") or "") if row.get("remote") is True else ""
    return profile_key(machine, row.get("sourceId") or row.get("provider") or "")


def filter_profiles(dashboard):
    """The popover profile model: this machine first, then other machines by name.
    Each machine is {"machine", "machineName", "apps"} and each app is {"provider", "profiles"};
    each profile is {"key", "label", "color"}. Apps follow APP_ORDER; profiles keep source order."""
    local_name = ""
    for row in dashboard.get("threads", []):
        if row.get("remote") is not True and row.get("machineName"):
            local_name = str(row["machineName"])
            break
    local = []
    seen = set()
    for entry in dashboard.get("providers", []):
        provider = entry.get("provider")
        if not provider or entry.get("id") in seen:
            continue
        seen.add(entry.get("id"))
        local.append({"key": profile_key("", entry.get("id") or ""), "label": str(entry.get("label") or ""),
                      "color": str(entry.get("color") or ""), "provider": provider, "source": ""})
    remote = {}
    for row in dashboard.get("threads", []):
        if row.get("remote") is not True:
            continue
        machine = str(row.get("machineId") or "")
        source_id = row.get("sourceId") or row.get("provider") or ""
        key = profile_key(machine, source_id)
        if key in seen:
            continue
        seen.add(key)
        provider = row.get("provider") or ""
        label = row.get("sourceLabel") or (APP_NAMES.get(provider, provider) if source_id == provider else source_id)
        entry = {"key": key, "label": str(label), "color": str(row.get("sourceColor") or ""),
                 "provider": provider, "source": machine, "machineName": str(row.get("machineName") or machine)}
        remote.setdefault(machine, []).append(entry)

    def by_app(entries):
        groups = {}
        for entry in entries:
            groups.setdefault(entry["provider"], []).append(entry)
        apps = []
        for provider in sorted(groups, key=order_of):
            apps.append({"provider": provider,
                         "profiles": tuple({"key": item["key"], "label": item["label"], "color": item["color"]}
                                           for item in groups[provider])})
        return tuple(apps)

    machines = [{"machine": "", "machineName": local_name or "This machine", "apps": by_app(local)}]
    for machine in sorted(remote, key=lambda name: (remote[name][0].get("machineName", name), name)):
        entries = sorted(remote[machine], key=lambda item: (order_of(item["provider"]), item["label"]))
        machines.append({"machine": machine, "machineName": remote[machine][0].get("machineName") or machine,
                         "apps": by_app(entries)})
    return tuple(machines)


def filtered_rows(dashboard, query="", app="all", state="all", archived=False, pending_only=False, drawer_only=False, profiles=None):
    query, app = provider_query(query, app)
    # An empty state set means every state; a missing profile set means every profile.
    states = set(STATES) if state == "all" or not state else {state} if isinstance(state, str) else set(state)
    wanted = frozenset(profiles or ())
    working_or_unread = pending_only and states == {"working"}
    rows = [row for row in dashboard.get("threads", [])
            if (archived or not row.get("archived"))
            and (not drawer_only or row.get("drawer"))
            and (app == "all" or row.get("provider") in ({app} if isinstance(app, str) else app))
            and (not wanted or row_profile_key(row) in wanted)
            and ((row.get("state") == "working" or row.get("pending") or row.get("unread") or row.get("questionAttention"))
                 if working_or_unread else row.get("state") in states and (not pending_only or row.get("pending")))
            and (not query or query in "\n".join(str(row.get(key, "")) for key in
                 ("title", "projectName", "cwd", "providerLabel", "sourceLabel")).casefold())]
    # One card for each ID: the first row wins. A card in a column twice makes GTK list it twice, with no warning.
    rows = list({row["id"]: row for row in reversed(rows)}.values())
    def bucket(row):
        if row.get("pending"):
            return 0
        return {"working": 1, "idle": 2, "waiting": 2, "unknown": 3}.get(row.get("state"), 3)
    def moment(row):
        # Output changes updatedAtMs at each scan; the task start keeps a Working row in its place.
        if row.get("state") != "working":
            # A muted row waits with the Idle rows from the time of its mute, as if it had just finished.
            return max(row.get("updatedAtMs", 0), row.get("mutedAtMs") or 0)
        start = row.get("workingSinceMs")
        return start if type(start) in (int, float) and start > 0 else 0
    def mark(row):
        # Pending rows sort by the mark that the card shows: a Working ?, any other ?, !, the dot, then the rest.
        if not row.get("pending"):
            return row.get("state") != "working"
        indicator = attention_indicator(row, True)
        return 0 if indicator == "question" and row.get("state") == "working" else \
            {"question": 1, "alert": 2, "dot": 3}.get(indicator, 4)
    rows.sort(key=lambda row: (0, row.get("pinIndex", 0), row["id"]) if row.get("pinned") else
              (1, bucket(row), mark(row), -moment(row), row["id"]))
    return rows


def limit_rows(rows, limit, show_all=False):
    """The first `limit` rows and one More row for the rest. A limit of 0 or show_all keeps every row."""
    if not limit or show_all or len(rows) <= limit:
        return rows
    rest = rows[limit:]
    return rows[:limit] + [{"id": MORE_ID, "provider": "", "providerLabel": "", "title": "More sessions", "state": "idle",
                            "canOpen": False, "updatedAtMs": max(row.get("updatedAtMs", 0) for row in rest),
                            "asbMore": len(rest), "asbLimit": limit, "asbFirst": rest[0]["id"]}]


def read_text_scale(settings):
    """The GNOME text scale: gtk-xft-dpi is 1024 times the dots per inch, and 96 dpi is 1.0; unset is 1.0."""
    dpi = settings.get_property("gtk-xft-dpi")
    return dpi / (96 * 1024) if dpi > 0 else 1.0


def pack_columns(rows, width, height, column_width=DEFAULT_COLUMN_WIDTH, row_height=ROW_HEIGHT):
    columns = max(1, (width + 12) // (column_width + 12))
    capacity = max(1, (height - 4) // row_height)
    parts = [rows[start:start + capacity] for start in range(0, len(rows), capacity)]
    return columns, capacity, parts


def column_cards(listing):
    """The cards of a column that are widget children, in the order GTK draws them."""
    cards, card = [], listing.get_first_child()
    while card:
        cards.append(card)
        card = card.get_next_sibling()
    return cards


def listed_cards(listing):
    """The cards in the internal list of a column. GTK lays out this list: an entry that is no widget child leaves an empty slot."""
    cards, card = [], listing.get_row_at_index(0)
    while card is not None:
        cards.append(card)
        card = listing.get_row_at_index(len(cards))
    return cards


def column_moves(current, target):
    """The cards to take out of a column and the (index, card) inserts, in index order, that turn current into target.
    The longest run of cards that already has the target order stays in place."""
    place = {card: index for index, card in enumerate(target)}
    kept = [place[card] for card in current if card in place]
    tails, previous = [], [None] * len(kept)
    for position, index in enumerate(kept):
        low, high = 0, len(tails)
        while low < high:
            middle = (low + high) // 2
            if kept[tails[middle]] < index:
                low = middle + 1
            else:
                high = middle
        previous[position] = tails[low - 1] if low else None
        tails[low:low + 1] = [position]
    stay, position = set(), tails[-1] if tails else None
    while position is not None:
        stay.add(target[kept[position]])
        position = previous[position]
    return [card for card in current if card not in stay], [(index, card) for index, card in enumerate(target) if card not in stay]


# MSYS2 has no Python qrcode package, so the board on Windows shows no QR code.
QR_HELP = ("Windows shows no QR code. Use Copy link." if os.name == "nt"
           else "Install the Python qrcode module and PyGObject cairo support. Run asb doctor for the command.")
THEME_KEYS = ("background", "text", "accent", "muted", "divider")


def config_dir(env=os.environ, os_name=os.name):
    """The ASB config folder (configDir in src/platform-paths.mjs); on Linux a relative XDG_CONFIG_HOME stays as it is."""
    if os_name == "nt":
        appdata = env.get("APPDATA", "")
        return (Path(appdata) if ntpath.isabs(appdata) else Path.home() / "AppData" / "Roaming") / "asb"
    return Path(env.get("XDG_CONFIG_HOME") or Path.home() / ".config") / "asb"


THEME_PATH = config_dir() / "theme.json"
LAYOUT_PATH = THEME_PATH.with_name("layout.json")


def number_key_rows(rows, bounds, viewport):
    """The IDs that Ctrl+1 to Ctrl+9 open: openable rows fully in the viewport, in board order."""
    width, height = viewport
    keys = []
    for row in rows:
        box = bounds.get(row["id"])
        if row.get("canOpen") and box and box[2] > 0 and box[3] > 0 and width > 0 and height > 0 \
                and box[0] >= -.5 and box[1] >= -.5 and box[0] + box[2] <= width + .5 and box[1] + box[3] <= height + .5:
            keys.append(row["id"])
            if len(keys) == 9:
                break
    return keys


def number_key(keyval):
    """1 to 9 for the digit and keypad digit keys (X keysyms), else 0."""
    return keyval - 0x30 if 0x31 <= keyval <= 0x39 else keyval - 0xffb0 if 0xffb1 <= keyval <= 0xffb9 else 0


def motion_allowed(previous, current, animations, mapped):
    # The first render and a change of columns, capacity, column width, or view show the result at once.
    return bool(animations and mapped and previous is not None and previous[1:5] == current[1:5])


def motion_offsets(old, new):
    """Paint offsets (x, y, missing opacity) from the old painted places; a card with no old place fades in."""
    offsets = {}
    for identity, place in new.items():
        before = old.get(identity)
        offset = (before[0] - place[0], before[1] - place[1], before[2]) if before else (0, 0, 1)
        if any(offset):
            offsets[identity] = offset
    return offsets


def glide_epsilon(distance):
    """The largest spring epsilon from .0001 to .001 for which a card that moves DISTANCE px jumps at most half a pixel
    when the glide ends. libadwaita ends this critically damped spring (stiffness 400) at -ln(epsilon) / 20 s, where
    epsilon * (1 - ln epsilon) of the move is left. The jump grows with epsilon, so a bisection finds the bound."""
    def jump(epsilon):
        return distance * epsilon * (1 - math.log(epsilon))
    low, high = .0001, .001
    if jump(high) <= .5:
        return high
    if jump(low) > .5:
        return low
    for _ in range(40):
        middle = (low + high) / 2
        low, high = (middle, high) if jump(middle) <= .5 else (low, middle)
    return low


MESSAGE_MAX_AGE_MS = 30_000
MESSAGE_FLIGHT_LIMIT = 6
MESSAGE_LIGHT_MS = 2000


def new_messages(messages, seen, visible, now_ms, room):
    """Message keys to play now and the keys to keep as seen; the first dashboard (seen None) plays nothing."""
    keys, play, pairs = set(), [], set()
    for message in messages if isinstance(messages, list) else []:
        if not isinstance(message, dict):
            continue
        source, target, at = message.get("from"), message.get("to"), message.get("atMs")
        if not isinstance(source, str) or not isinstance(target, str) or type(at) not in (int, float):
            continue
        key = (source, target, at)
        keys.add(key)
        if seen is None or key in seen or now_ms - at > MESSAGE_MAX_AGE_MS or source == target \
                or source not in visible or target not in visible or (source, target) in pairs or len(play) >= room:
            continue
        pairs.add((source, target))
        play.append(key)
    return play, keys


def message_duration(distance):
    return min(900, max(480, distance / 1.5))


def message_control(start, end):
    """Quadratic Bezier control point: bow to the upper side for mostly horizontal travel, else to the left."""
    dx, dy = end[0] - start[0], end[1] - start[1]
    distance = math.hypot(dx, dy)
    x, y = (start[0] + end[0]) / 2, (start[1] + end[1]) / 2
    if distance:
        bow = min(60, .22 * distance)
        nx, ny = -dy / distance, dx / distance
        sign = -1 if (ny > 0 if abs(dx) >= abs(dy) else nx > 0) else 1
        x, y = x + sign * nx * bow, y + sign * ny * bow
    return max(2, x), y


def bezier_point(start, control, end, t):
    u = 1 - t
    return tuple(u * u * a + 2 * u * t * b + t * t * c for a, b, c in zip(start, control, end))


def ease_in_out_cubic(t):
    return 4 * t ** 3 if t < .5 else 1 - (-2 * t + 2) ** 3 / 2


def message_tail(t):
    """Tail segments (from, to, width, alpha) behind the head at linear time t, in eased path progress.
    The steps are in time, so the tail stretches with the speed of the light; it stops at 0."""
    segments = []
    for k in range(1, 9):
        first = t - (k - 1) * .025
        if first <= 0:
            break
        segments.append((ease_in_out_cubic(first), ease_in_out_cubic(max(0, t - k * .025)),
                         3.2 * (1 - k / 9), .7 * (1 - k / 9)))
    return segments


def message_edge(x, left, right):
    """An x outside the viewport moves to the edge on that side, 2 px inside."""
    return left + 2 if x < left else right - 2 if x > right else x


def edge_alpha(ms):
    """Edge mark: 0 to 1 in 120 ms, hold 300 ms, to 0 in 300 ms."""
    return max(0, min(1, ms / 120, 1 - (ms - 420) / 300))


PET_FILE = Path(__file__).parents[1] / "assets" / "pets" / "pets.json"
PET_FRAMES = ("stand", "walk1", "walk2", "walk3", "walk4", "crouch", "air", "air2", "toss", "release")


def pet_runs(grid, palette, accent=False):
    """(color, x, y, width) for each run of equal keys, row by row; with accent, the key A is the board accent (None)."""
    runs = []
    for y, row in enumerate(grid):
        x = 0
        while x < len(row):
            end = x
            while end < len(row) and row[end] == row[x]:
                end += 1
            if row[x] != ".":
                runs.append((None if accent and row[x] == "A" else palette[row[x]], x, y, end - x))
            x = end
    return runs


def pet_pair(value, reason):
    if not isinstance(value, list) or len(value) != 2 or any(type(item) is not int for item in value):
        raise ValueError(reason)
    return tuple(value)


def pet_grid(palette, grid, width, height, keys=frozenset(".")):
    if not isinstance(palette, dict) or any(not isinstance(color, str) or not re.fullmatch(r"#[0-9a-fA-F]{6}", color)
                                            for color in palette.values()):
        raise ValueError("a palette value is not #rrggbb")
    if not isinstance(grid, list) or len(grid) != height or any(not isinstance(row, str) or len(row) != width for row in grid):
        raise ValueError(f"a grid is not {height} rows of {width} characters")
    if set("".join(grid)) - set(palette) - keys:
        raise ValueError("a grid key is not in its palette")
    return grid


def parse_pets(data):
    if type(data["version"]) is not int or data["version"] != 1:
        raise ValueError("the version is not 1")
    letter = data["envelope"]
    if letter["width"] != 8 or letter["height"] != 6:
        raise ValueError("the envelope is not 8 × 6")
    envelope = tuple(pet_runs(pet_grid(letter["palette"], letter["grid"], 8, 6, frozenset(".A")), letter["palette"], accent=True))
    pets = {}
    for name in PETS[1:]:
        if name not in data["pets"]:
            raise ValueError(f"the {name} is missing")
        item = data["pets"][name]
        width, height, palette = item["width"], item["height"], item["palette"]
        anchor = pet_pair(item["anchor"], f"the {name} anchor is not two integers")
        mirror, front, fps = item["mirror"], item["envelopeFront"], item["walkFps"]
        if type(mirror) is not bool or type(front) is not bool:
            raise ValueError(f"mirror or envelopeFront of the {name} is not true or false")
        if type(fps) is not int or fps < 1:
            raise ValueError(f"walkFps of the {name} is not a positive integer")
        frames = {}
        for frame in PET_FRAMES:
            if frame not in item["frames"]:
                raise ValueError(f"the {name} frame {frame} is missing")
            value = item["frames"][frame]
            grid = pet_grid(palette, value["grid"], width, height)
            if not isinstance(value["over"], list):
                raise ValueError(f"over of the {name} {frame} is not a list")
            over = [pet_pair(pixel, f"over of the {name} {frame} is not two integers") for pixel in value["over"]]
            if any(not 0 <= x < width or not 0 <= y < height for x, y in over):
                raise ValueError(f"over of the {name} {frame} is outside the frame")
            right = pet_runs(grid, palette)
            left = [(color, width - x - length, y, length) for color, x, y, length in right]
            held = None
            if value["envelope"] is not None:
                ex, ey = pet_pair(value["envelope"], f"the envelope of the {name} {frame} is not two integers")
                held = ((ex, ey), (width - 8 - ex, ey) if mirror else (ex, ey))
                letters = [[(color, held[side][0] + x, ey + y, length) for color, x, y, length in envelope] for side in (0, 1)]
                if front:
                    right += letters[0] + [(palette[grid[y][x]], x, y, 1) for x, y in over]
                    left += letters[1] + [(palette[grid[y][x]], width - 1 - x, y, 1) for x, y in over]
                else:
                    right, left = letters[0] + right, letters[1] + left
            frames[frame] = {"runs": (tuple(right), tuple(left) if mirror else tuple(right)), "envelope": held}
        pets[name] = {"width": width, "height": height, "anchor": anchor, "mirror": mirror, "walkFps": fps,
                      "reach": width - anchor[0], "frames": frames}
    return {"envelope": {"width": 8, "height": 6, "runs": envelope}, "pets": pets}


@functools.lru_cache(maxsize=None)
def load_pets(path=PET_FILE):
    """The board pets as paint runs in sprite pixels (see assets/pets/README.md)."""
    try:
        return parse_pets(json.loads(Path(path).read_text(encoding="utf-8")))
    except (ValueError, KeyError, TypeError, AttributeError) as error:
        raise ValueError(f"The pets file is not valid: {error}") from None


def pet_sign(value):
    return (value > 0) - (value < 0)


def pet_round(value):
    # Math.round of the approved preview: halves go up.
    return math.floor(value + .5)


def pet_tile_pose(t):
    """The frame and vertical offset of a tile choice, in ms; None at rest."""
    if 0 <= t < 80 or 240 <= t < 320:
        return "crouch", 0
    if 80 <= t < 240:
        return ("air" if t - 80 < 90 else "air2"), -8 * math.sin(math.pi * (t - 80) / 160)
    return None


def pet_stop(pet, scale, receiver_x, direction):
    # Comfortable: the pet stands below the icon. Compact: the icon is level with the pet, so its front edge stops 12 px from the icon center.
    return receiver_x - direction * (12 if scale > 1 else 12 + pet["reach"])


def pet_walk_ms(distance):
    # The preview speed up to 600 px; a longer walk takes 2 s, so a wide board does not keep a flight slot for long.
    return distance / max(min(300, max(120, distance / 1.1)), distance / 2) * 1000 if distance else 0


def pet_jump_y(y0, y1, height, u):
    """A parabola from y0 to y1 whose top is height above the higher floor."""
    top = min(y0, y1) - height
    a = y0 - top
    k = (y1 - y0) + 2 * a + 2 * math.sqrt(a * (y1 - top))
    return y0 + (y1 - y0) * u - k * u * (1 - u)


def pet_plan(pet, scale, sender, receiver):
    """The phases (name, start, end) in ms of one pet message, from the positions at the start."""
    sx, _sy, fs = sender
    rx, _ry, fr = receiver
    direction = pet_sign(rx - sx) or -1
    stop = pet_stop(pet, scale, rx, direction)
    same_row = abs(fr - fs) < 1
    steps = [("rise", 380)]
    if same_row:
        steps.append(("walk", pet_walk_ms(abs(stop - sx))))
    else:
        if abs(stop - sx) > 14 * scale:
            steps.append(("walk", pet_walk_ms(abs(stop - pet_sign(stop - sx) * 14 * scale - sx))))
        steps += [("crouch", 80), ("jump", min(620, max(300, 260 + .5 * abs(fr - fs)))), ("land", 80)]
    steps += [("windup", 120), ("toss", 240), ("hop", 160), ("dive", 320)]
    phases, t = [], 0
    for name, duration in steps:
        if duration > 0:
            phases.append((name, t, t + duration))
            t += duration
    return {"direction": direction, "same_row": same_row, "phases": phases,
            "ta": next(end for name, _start, end in phases if name == "toss"), "end": t + 200}


def pet_pose(pet, scale, plan, t, sender, receiver):
    """The frame, the feet point, the facing, and the floor clip of the pet at t, from the positions now; None after the dive."""
    phase = next((phase for phase in plan["phases"] if phase[1] <= t < phase[2]), None)
    if phase is None:
        return None
    name, start, end = phase
    sx, _sy, fs = sender
    rx, _ry, fr = receiver
    lt = t - start
    u = lt / (end - start)
    d = plan["direction"]
    stop = pet_stop(pet, scale, rx, d)
    jx = stop - pet_sign(stop - sx) * 14 * scale if abs(stop - sx) > 14 * scale else sx
    first = pet_sign(stop - sx) or d
    jump_face = pet_sign(stop - jx) or d
    h = pet["height"]
    if name == "rise":
        back = 1 + 2.4 * (u - 1) ** 3 + 1.4 * (u - 1) ** 2
        return {"frame": "air" if u < .7 else "stand", "x": sx, "y": fs + h * scale * (1 - back), "face": first, "clip": fs}
    if name == "walk":
        x1 = stop if plan["same_row"] else jx
        return {"frame": ("walk1", "walk2", "walk3", "walk4")[math.floor(lt * pet["walkFps"] / 1000) % 4],
                "x": sx + (x1 - sx) * u, "y": fs, "face": first, "clip": None}
    if name == "crouch":
        return {"frame": "crouch", "x": jx, "y": fs, "face": jump_face, "clip": None}
    if name == "jump":
        height = max(0, min(9 * scale, min(fs, fr) - h * scale - 2))
        return {"frame": "air2" if math.floor(lt / 90) % 2 else "air", "x": jx + (stop - jx) * u,
                "y": pet_jump_y(fs, fr, height, u), "face": jump_face, "clip": None}
    # From the toss on, the paws are empty: the envelope never shows in the pet again.
    frame, y, clip = {"land": ("crouch", fr, None), "windup": ("toss", fr, None), "toss": ("release", fr, None),
                      "hop": ("release", fr - 4 * scale * math.sin(math.pi * u), None),
                      "dive": ("release", fr + h * scale * u ** 3, fr)}[name]
    return {"frame": frame, "x": stop, "y": y, "face": d, "clip": clip}


def pet_box(pet, scale, frame, x, y, face):
    """(runs, left, top, flip) of a frame with its feet at (x, y)."""
    flip = pet["mirror"] and face < 0
    ax = pet["width"] - pet["anchor"][0] if flip else pet["anchor"][0]
    return (pet["frames"][frame]["runs"][1 if flip else 0], pet_round(x - ax * scale),
            pet_round(y - pet["height"] * scale), flip)


def pet_envelope(pet, scale, plan, t, receiver):
    """The top-left of the flying envelope during the toss, else None."""
    _name, start, end = next(phase for phase in plan["phases"] if phase[0] == "toss")
    if not start <= t < end:
        return None
    rx, ry, fr = receiver
    d = plan["direction"]
    _runs, left, top, flip = pet_box(pet, scale, "toss", pet_stop(pet, scale, rx, d), fr, d)
    ex, ey = pet["frames"]["toss"]["envelope"][1 if flip else 0]
    x0, y0, x1, y1 = left + ex * scale, top + ey * scale, rx - 4 * scale, ry - 3 * scale
    cx, cy = (x0 + x1) / 2, min(y0, y1) - 9 * scale
    p = 1 - (1 - (t - start) / (end - start)) ** 2
    q = 1 - p
    return (pet_round(q * q * x0 + 2 * q * p * cx + p * p * x1), pet_round(q * q * y0 + 2 * q * p * cy + p * p * y1))


def pet_particles(pet, scale, plan, t, sender, receiver):
    """The (x, y, alpha) of each 2 × 2 px particle at t: ground puffs at the start and the dive, sparkles at the icon."""
    sx, _sy, fs = sender
    rx, ry, fr = receiver
    ground = (200, 250, 290, 340)
    dive = next(start for name, start, _end in plan["phases"] if name == "dive")
    bursts = ((sx, fs - 1, 0, ground), (rx, ry, plan["ta"], range(0, 360, 45)),
              (pet_stop(pet, scale, rx, plan["direction"]), fr - 1, dive, ground))
    particles = []
    for cx, cy, start, angles in bursts:
        v = (t - start) / 360
        if not 0 <= v < 1:
            continue
        radius = (5 + 11 * (1 - (1 - v) ** 3)) * scale / 2
        alpha = 1 if v < .5 else 1 - (v - .5) / .5
        particles += [(pet_round(cx + radius * math.cos(math.radians(angle)) - 1), pet_round(cy + radius * math.sin(math.radians(angle)) - 1), alpha)
                      for angle in angles]
    return particles


def pet_tints(plan, t):
    """{row index: alpha} of the card tints: the sender at the start, the receiver from just before the toss lands."""
    tints = {}
    for index, start, end in ((0, 0, 520), (1, plan["ta"] - 120, plan["end"])):
        if start <= t < end:
            alpha = max(0, min(1, (t - start) / 120, (end - t) / 240))
            if alpha > 0:
                tints[index] = alpha
    return tints


def luminance(color):
    channels = [int(color[index:index + 2], 16) / 255 for index in (1, 3, 5)]
    return sum((value / 12.92 if value <= .04045 else ((value + .055) / 1.055) ** 2.4) * weight
               for value, weight in zip(channels, (.2126, .7152, .0722)))


def contrast(first, second):
    light, dark = sorted((luminance(first), luminance(second)), reverse=True)
    return (light + .05) / (dark + .05)


def mix_color(background, foreground, fraction):
    return "#" + "".join(f"{round(int(background[start:start + 2], 16) * (1 - fraction) + int(foreground[start:start + 2], 16) * fraction):02x}"
                         for start in (1, 3, 5))


def validate_source_color(value):
    if not isinstance(value, str) or not re.fullmatch(r"#[0-9a-fA-F]{6}", value):
        raise ValueError("Profile color must use a #RRGGBB value.")
    return value.lower()


def display_source_color(color, surfaces):
    for percent in range(101):
        displayed = mix_color(color, "#ffffff", percent / 100)
        if all(contrast(displayed, surface) >= 3 for surface in surfaces):
            return displayed
    return ""


def highlight_color(colors):
    return mix_color(colors["background"], colors["accent"], .15)


def quiet_color(colors, key, fraction, highlight):
    surfaces = (colors["background"], highlight)
    for percent in range(round(fraction * 100), 101):
        color = mix_color(colors["background"], colors[key], percent / 100)
        if all(contrast(color, surface) >= 4.5 for surface in surfaces):
            return color, percent / 100
    return colors[key], 1


def lightness(color):
    """CIE L* (D65) of an sRGB hex color, 0 to 100."""
    y = luminance(color)
    return 116 * y ** (1 / 3) - 16 if y > 216 / 24389 else 24389 / 27 * y


def quiet_tones(colors, highlight, custom):
    """The quiet title and caption colors with their fractions. The caption is at least 10 L* below the title:
    first the caption goes down to its 4.5:1 floor, then the title goes up."""
    key = "muted" if custom else "text"
    title, title_fraction = quiet_color(colors, "text", .67, highlight)
    caption, caption_fraction = quiet_color(colors, key, .85 if custom else .5, highlight)
    if lightness(title) - lightness(caption) >= 10:
        return (title, title_fraction), (caption, caption_fraction)
    floor = quiet_color(colors, key, 0, highlight)[1]
    for percent in range(round(caption_fraction * 100), round(floor * 100) - 1, -1):
        caption, caption_fraction = mix_color(colors["background"], colors[key], percent / 100), percent / 100
        if lightness(title) - lightness(caption) >= 10:
            return (title, title_fraction), (caption, caption_fraction)
    for percent in range(round(title_fraction * 100), 101):
        title, title_fraction = mix_color(colors["background"], colors["text"], percent / 100), percent / 100
        if lightness(title) - lightness(caption) >= 10:
            break
    return (title, title_fraction), (caption, caption_fraction)


def limited_color(colors):
    """The text color of a limited row: the dimmest mix of text into the background with 4.5:1 on the background."""
    return quiet_color(colors, "text", 0, colors["background"])


def contrast_floor(color, ink, surface, minimum=4.5):
    """The weakest mix of ink into color with the minimum contrast on the surface."""
    for percent in range(101):
        value = mix_color(color, ink, percent / 100)
        if contrast(value, surface) >= minimum:
            return value
    return ink


def accent_guard(color, accent, window):
    """Separate a fixed data color from a similar accent, changing only OKLCH lightness before sRGB gamut mapping.
    Two triggers: a similar chromatic hue with low contrast (target 2:1 on the accent), or an OKLab distance under 0.09 at any
    chroma and hue (target a distance of 0.09 or more); both targets also need 3:1 on the window. Lightness first moves away from
    the accent lightness; the first passing color the other way wins only when its chroma is more than 0.01 higher."""
    lightness, a, b = oklab(color)
    accent_lab = oklab(accent)
    accent_lightness, aa, ab = accent_lab
    chroma, accent_chroma = math.hypot(a, b), math.hypot(aa, ab)
    hue, accent_hue = math.degrees(math.atan2(b, a)) % 360, math.degrees(math.atan2(ab, aa)) % 360
    distance = abs((hue - accent_hue + 180) % 360 - 180)
    similar = chroma >= .04 and accent_chroma >= .04 and distance < 30 and contrast(color, accent) < 1.5
    near = math.dist((lightness, a, b), accent_lab) < .09
    if not similar and not near:
        return color
    def first(sign):
        step = lightness
        while 0 < step < 1:
            step = max(0, min(1, step + sign * .005))
            candidate = oklch_color(step, chroma, hue)
            if (contrast(candidate, window) >= 3 and (not similar or contrast(candidate, accent) >= 2)
                    and (not near or math.dist(oklab(candidate), accent_lab) >= .09)):
                return candidate
        return None
    direction = -1 if lightness <= accent_lightness else 1
    away, other = first(direction), first(-direction)
    # The other direction wins only with clearly more chroma after gamut mapping, so an error color does not turn near-white.
    if away and other and math.hypot(*oklab(other)[1:]) > math.hypot(*oklab(away)[1:]) + .01:
        return other
    return away or other or color


def row_panel_colors(colors, caption, surface=None):
    """The row panel roles. Custom colors raise the surface 10% toward the text; GNOME colors give the popover surface.
    The floor is the dimmest text with 4.5:1 on the surface, and the Mute tag off dots get 3:1 on their tag."""
    custom = surface is None
    surface = surface or mix_color(colors["background"], colors["text"], .10)
    edge = edge_color(colors["background"], colors["text"], .36, (colors["background"],)) if custom else mix_color(surface, colors["text"], .15)
    return {"surface": surface, "edge": edge, "muted": contrast_floor(colors["muted"], colors["text"], surface), "separator": mix_color(surface, colors["text"], .15),
            "floor": quiet_color({"background": surface, "text": colors["text"]}, "text", 0, surface),
            "dot": contrast_floor(caption, colors["text"], mix_color(surface, colors["text"], .12), 3)}


def number_badge_colors(colors):
    """Custom Ctrl-number badge: 17% text into the background, less only as far as the text needs for 4.5:1."""
    for percent in range(17, -1, -1):
        fill = mix_color(colors["background"], colors["text"], percent / 100)
        if contrast(colors["text"], fill) >= 4.5:
            break
    pressed = max(("#000000", "#ffffff"), key=lambda ink: contrast(colors["accent"], ink))
    return fill, mix_color(colors["background"], colors["text"], .36), pressed


def validate_theme(value):
    if not isinstance(value, dict) or set(value) != set(THEME_KEYS):
        raise ValueError("Choose a color for each theme field.")
    if any(not isinstance(color, str) or not re.fullmatch(r"#[0-9a-fA-F]{6}", color) for color in value.values()):
        raise ValueError("Colors must use #RRGGBB values.")
    if luminance(value["background"]) > .12:
        raise ValueError("Choose a dark background.")
    for key in ("text", "muted", "accent"):
        for surface, color in (("background", value["background"]), ("highlight", highlight_color(value))):
            if contrast(value[key], color) < 4.5:
                raise ValueError(f"{key.capitalize()} needs at least 4.5:1 contrast with the {surface}.")
    return {key: value[key].lower() for key in THEME_KEYS}


def read_theme(path):
    if not path or not Path(path).exists():
        return None
    value = json.loads(Path(path).read_text())
    if not isinstance(value, dict) or value.get("mode") != "custom":
        raise ValueError("The saved ASB theme is not valid. Reset it to GNOME.")
    return validate_theme(value.get("colors"))


def write_config(path, value):
    if not path:
        return
    path = Path(path)
    if value is None:
        path.unlink(missing_ok=True)
        return
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", dir=path.parent, prefix=".asb-", delete=False) as stream:
            temporary = Path(stream.name)
            json.dump(value, stream)
        temporary.replace(path)
    finally:
        if temporary:
            temporary.unlink(missing_ok=True)


def write_theme(path, colors=None):
    write_config(path, None if colors is None else {"mode": "custom", "colors": validate_theme(colors)})


def palette_payload(custom, native=None, success=None, warning=None):
    """The palette for POST /api/palette: custom colors, or the GNOME colors with the GNOME success and warning colors."""
    if custom:
        return {"mode": "custom", "colors": {**{key: custom[key] for key in THEME_KEYS},
                                             "success": custom["accent"], "warning": custom["accent"]}}
    return {"mode": "gnome", "colors": {**{key: native[key] for key in THEME_KEYS},
                                        "success": success or native["accent"], "warning": warning or native["accent"]}}


def validate_column_width(width):
    if type(width) is not int or not 160 <= width <= 600:
        raise ValueError("Column width must be a whole number from 160 to 600 pixels.")
    return width


# Board zoom levels in percent (Ctrl+wheel on the board); 100 is the default.
ZOOM_LEVELS = (80, 90, 100, 110, 125, 150, 175, 200)
ZOOM_SIZE = re.compile(r"\b(font-size|min-height|min-width|line-height):\s*(\d+(?:\.\d+)?)px")
ZOOM_SCOPE = re.compile(r"\.asb-column-flow(?:\.[\w-]+|:not\([^()]*\))*\s")


def validate_zoom(value):
    if type(value) is not int or value not in ZOOM_LEVELS:
        raise ValueError("The board zoom must be 80, 90, 100, 110, 125, 150, 175, or 200 percent.")
    return value


def zoom_step(zoom, steps):
    """The zoom level `steps` levels above (positive) or below `zoom`, within ZOOM_LEVELS."""
    index = ZOOM_LEVELS.index(zoom) if zoom in ZOOM_LEVELS else ZOOM_LEVELS.index(100)
    return ZOOM_LEVELS[max(0, min(len(ZOOM_LEVELS) - 1, index + steps))]


def zoom_wheel_step(total, dy, surface=False):
    """(steps, total): Ctrl+wheel up zooms in. A wheel notch is one level; touchpad deltas add up to one level per 40 pixels."""
    total += dy
    limit = 40 if surface else 1
    if abs(total) < limit:
        return 0, total
    return (-1 if total > 0 else 1), 0.0


def zoomed(px, zoom):
    """A board size in px at the zoom, rounded as zoom_css rounds the CSS sizes."""
    return round(px * zoom / 100)


def corner_reserve(zoom):
    """The Read and pin slots, their gap and end margin at the zoom, less the 1 px card border; 54 px at 100%."""
    return 2 * zoomed(24, zoom) + zoomed(2, zoom) + zoomed(5, zoom) - 1


def zoom_css(css, zoom):
    """Scale board and tooltip sizes, but keep Preferences and all other sizes unchanged."""
    if zoom == 100:
        return css
    def rule(match):
        selectors, body = match.group(1), match.group(2)
        scaled = ZOOM_SIZE.sub(lambda size: f"{size.group(1)}: {zoomed(float(size.group(2)), zoom)}px", body)
        parts, start, depth = [], 0, 0
        for token in re.finditer(r"[(),]", selectors):
            if token[0] == "(":
                depth += 1
            elif token[0] == ")":
                depth -= 1
            elif depth == 0:
                parts.append(selectors[start:token.start()].strip())
                start = token.end()
        parts.append(selectors[start:].strip())
        rules = []
        # One extra class per selector preserves specificity and source order at every zoom.
        for selector in parts:
            if ZOOM_SCOPE.search(selector) and "asb-preferences" not in selector and not re.search(
                    r"\.asb-(?:toolbar(?:-button)?|filter-(?:pill|row|head|footer)|chip-(?:dot|scroll)|drawer-(?:dot|glyph|handle))(?![\w-])", selector):
                rules.append(selector.replace(".asb-column-flow", ".asb-column-flow:not(.asb-preferences)", 1) + " {" + scaled + "}")
                rules.append(selector.replace(".asb-column-flow", ".asb-column-flow.asb-preferences", 1) + " {" + body + "}")
            else:
                tooltip = re.match(r"^[^\s>+~]*\.asb-tooltip(?![\w-])", selector)
                rules.append(selector + ":not(.asb-zoom-none) {" + (scaled if tooltip else body) + "}")
        return ("\n" if match.start() else "") + "\n".join(rules)
    return re.sub(r"([^{}]+)\{([^{}]*)\}", rule, re.sub(r"/\*.*?\*/", "", css, flags=re.S))


def validate_card_limit(value):
    if type(value) is not int or value not in {limit for limit, _title in CARD_LIMITS}:
        raise ValueError("Cards on the board must be 50, 100, 200, 500, or All.")
    return value


def read_layout(path):
    if not path or not Path(path).exists():
        return {"columnWidth": DEFAULT_COLUMN_WIDTH, "view": "compact", "cardLimit": DEFAULT_CARD_LIMIT, "copyKind": "relative", "pet": "off", "muteFor": "30m",
                "zoom": 100}
    value = json.loads(Path(path).read_text())
    if not isinstance(value, dict) or not {"version", "columnWidth"}.issubset(value) \
            or set(value) - {"version", "columnWidth", "view", "showAppPills", "cardLimit", "copyKind", "pet", "muteFor", "zoom"} or value["version"] != 1:
        raise ValueError("The saved layout is not valid. Reset the width.")
    view = value.get("view", "compact")
    if view not in ("compact", "comfortable"):
        raise ValueError("Choose Compact or Comfortable view.")
    return {"columnWidth": validate_column_width(value["columnWidth"]), "view": view,
            "cardLimit": validate_card_limit(value.get("cardLimit", DEFAULT_CARD_LIMIT)),
            "copyKind": validate_copy_kind(value.get("copyKind", "relative")), "pet": validate_pet(value.get("pet", "off")),
            "muteFor": validate_mute_for(value.get("muteFor", "30m")), "zoom": validate_zoom(value.get("zoom", 100))}


def write_layout(path, width=None, view=None, card_limit=None, copy_kind=None, pet=None, mute_for=None, zoom=None):
    if view is None or card_limit is None or copy_kind is None or pet is None or mute_for is None or zoom is None:
        saved = read_layout(path)
        zoom = saved["zoom"] if zoom is None else zoom
        view = saved["view"] if view is None else view
        card_limit = saved["cardLimit"] if card_limit is None else card_limit
        copy_kind = saved["copyKind"] if copy_kind is None else copy_kind
        pet = saved["pet"] if pet is None else pet
        mute_for = saved["muteFor"] if mute_for is None else mute_for
    if view not in ("compact", "comfortable"):
        raise ValueError("Choose Compact or Comfortable view.")
    validate_card_limit(card_limit)
    validate_copy_kind(copy_kind)
    validate_pet(pet)
    validate_mute_for(mute_for)
    validate_zoom(zoom)
    if width is None and view == "compact" and card_limit == DEFAULT_CARD_LIMIT and copy_kind == "relative" and pet == "off" \
            and mute_for == "30m" and zoom == 100:
        write_config(path, None)
        return
    value = {"version": 1, "columnWidth": validate_column_width(DEFAULT_COLUMN_WIDTH if width is None else width)}
    if view == "comfortable":
        value["view"] = view
    if card_limit != DEFAULT_CARD_LIMIT:
        value["cardLimit"] = card_limit
    if copy_kind != "relative":
        value["copyKind"] = copy_kind
    if pet != "off":
        value["pet"] = pet
    if mute_for != "30m":
        value["muteFor"] = mute_for
    if zoom != 100:
        value["zoom"] = zoom
    write_config(path, value)


ACTIVITY_SIZE_KINDS = ("messages", "usage")


def valid_window_size(width, height, maximized):
    return all(type(value) is int and 360 <= value <= 16384 for value in (width, height)) and type(maximized) is bool


def read_window_sizes(path):
    """The saved Messages and Usage window sizes, {kind: (width, height, maximized)}; a missing, broken, or invalid file or kind gives none."""
    try:
        value = json.loads(Path(path).read_text())
    except (OSError, ValueError):
        return {}
    if not isinstance(value, dict) or value.get("version") != 1:
        return {}
    sizes = {}
    for kind in ACTIVITY_SIZE_KINDS:
        entry = value.get(kind)
        if isinstance(entry, dict) and valid_window_size(entry.get("width"), entry.get("height"), entry.get("maximized")):
            sizes[kind] = (entry["width"], entry["height"], entry["maximized"])
    return sizes


def write_window_size(path, kind, width, height, maximized):
    """Save one window size next to layout.json; layout.json keeps its keys, because older ASB versions reject unknown keys there."""
    if kind not in ACTIVITY_SIZE_KINDS or not valid_window_size(width, height, maximized):
        return
    sizes = read_window_sizes(path)
    sizes[kind] = (width, height, maximized)
    write_config(path, {"version": 1, **{name: {"width": w, "height": h, "maximized": m} for name, (w, h, m) in sizes.items()}})


def filter_chips(pending, states, profiles, profile_model, archived, show_all=False, limit=DEFAULT_CARD_LIMIT):
    """One chip per active filter value, in toolbar order. Each chip is (key, label, detail, color)."""
    chips = []
    if pending:
        chips.append(("pending", "Pending", "Remove filter: Pending", ""))
    chosen = set(states or ())
    for state in STATES:
        if state in chosen:
            chips.append((f"state:{state}", state.capitalize(), "Remove filter: " + state.capitalize(), ""))
    lookup = {profile["key"]: (profile, machine) for machine in profile_model for app in machine["apps"] for profile in app["profiles"]}
    order = [profile["key"] for machine in profile_model for app in machine["apps"] for profile in app["profiles"]]
    for key in order:
        if key not in set(profiles or ()):
            continue
        profile, machine = lookup[key]
        name = profile["label"]
        if machine["machine"]:
            name = f"{name} · {machine['machineName']}"
        chips.append((f"profile:{key}", name, "Remove filter: " + name, profile["color"]))
    if archived:
        chips.append(("archive", "Include archived", "Remove filter: Include archived", ""))
    if show_all and limit:
        chips.append(("all", "All cards", f"Show only the first {limit} cards", ""))
    return tuple(chips)


def working_duration(row, now_ms=None):
    now_ms = time.time() * 1000 if now_ms is None else now_ms
    start = row.get("workingSinceMs", 0)
    if row.get("state") != "working" or isinstance(start, bool) or not isinstance(start, (int, float)) or not 0 < start <= now_ms:
        return ""
    return duration_text(int((now_ms - start) / 1000))


def whole_minutes(seconds, round_up=False):
    """Whole minutes of a time: no time shows seconds. A Working time rounds down, a countdown rounds up."""
    return max(0, math.ceil(seconds / 60) if round_up else math.floor(seconds / 60))


def duration_text(seconds, round_up=False):
    """The Working time (round_up False) or a reset countdown (round_up True) in hours and minutes. A Working time shows <1m
    in its first minute."""
    minutes = whole_minutes(seconds, round_up)
    if not minutes:
        return "0m" if round_up else "<1m"
    hours, minutes = divmod(minutes, 60)
    return f"{hours}h{minutes:02d}m" if hours else f"{minutes}m"


def spoken_duration(seconds, round_up=False):
    minutes = whole_minutes(seconds, round_up)
    if not minutes:
        return "0 minutes" if round_up else "less than a minute"
    hours, minutes = divmod(minutes, 60)
    unit = lambda count, word: f"{count} {word}" + ("" if count == 1 else "s")
    if hours:
        return unit(hours, "hour") + (" " + unit(minutes, "minute") if minutes else "")
    return unit(minutes, "minute")


def limit_text(seconds):
    """The reset countdown: days and hours from 24 hours on (weekly limits), else hours and minutes, rounded up."""
    days, remainder = divmod(seconds, 86400)
    # Under one day a countdown rounds up to at most 23h59m, so 24h00m never shows before 1d00h.
    return f"{days}d{remainder // 3600:02d}h" if days else duration_text(min(seconds, 86_340), True)


def spoken_limit(seconds):
    days, remainder = divmod(seconds, 86400)
    if not days:
        return spoken_duration(min(seconds, 86_340), True)
    hours = remainder // 3600
    unit = lambda count, word: f"{count} {word}" + ("" if count == 1 else "s")
    return unit(days, "day") + (" " + unit(hours, "hour") if hours else "")


def limit_left(row, now_ms=None):
    """Whole seconds, rounded up, until the usage limit that stopped the row resets; 0 when no limit holds the row."""
    now_ms = time.time() * 1000 if now_ms is None else now_ms
    reset = row.get("limitResetsAtMs", 0)
    if isinstance(reset, bool) or not isinstance(reset, (int, float)) or not math.isfinite(reset) or reset <= now_ms or reset > 8.64e15:
        return 0
    return math.ceil((reset - now_ms) / 1000)


def clock_wait(threads, now_ms=None):
    """Seconds to the next local clock tick. Times show whole minutes, so the clock wakes when a Working time or a reset countdown
    reaches its next whole minute, when a timed mute ends or its caption changes, else after 60 seconds."""
    now_ms = time.time() * 1000 if now_ms is None else now_ms
    wait = 60
    for row in threads:
        if limit_left(row, now_ms):
            left = row["limitResetsAtMs"] - now_ms
            wait = min(wait, (left % 60_000 or 60_000) / 1000)
        if not row.get("archived") and working_duration(row, now_ms):
            elapsed = now_ms - row["workingSinceMs"]
            wait = min(wait, (60_000 - elapsed % 60_000) / 1000)
        if mute_active(row, now_ms) and mute_until_ms(row):
            left = mute_until_ms(row) - now_ms
            # At 24 rounded hours the caption stays 1d until it becomes 23h59m.
            change = left - 1439 * 60_000 if left > 1439 * 60_000 else (left % 60_000 or 60_000)
            wait = min(wait, left / 1000, change / 1000)
    return wait


def row_meta(row, now_ms=None):
    now_ms = now_ms if now_ms is not None else time.time() * 1000
    updated = row.get("updatedAtMs", 0)
    age = max(0, now_ms - updated)
    if not updated:
        date = "No date"
    elif age < 60_000:
        date = "Just now"
    elif age < 3_600_000:
        date = f"{int(age / 60_000)}m ago"
    elif age < 86_400_000:
        date = f"{int(age / 3_600_000)}h ago"
    else:
        date = f"{int(age / 86_400_000)}d ago"
    parts = [str(row.get("state", "unknown")).capitalize(), date]
    if row.get("pinned"):
        parts.append("Pinned")
    if row.get("archived"):
        parts.append("Archived")
    return " · ".join(parts)


def is_view_only(row):
    """A CLI session or a session on another machine shows as a card but does not open from ASB."""
    return bool(row.get("remote")) or row.get("surface") == "cli"


def row_where(row):
    """The (icon, text) that says where a view-only session runs; (None, "") for other rows."""
    if row.get("remote"):
        return "asb-machine-symbolic", row.get("machineName") or "another machine"
    if row.get("surface") == "cli":
        return "asb-terminal-symbolic", "CLI"
    return None, ""


def no_open_title(row):
    """The toast title that says why ASB does not open a card: the first rule that applies."""
    if row.get("remote"):
        machine = row.get("machineName") or "another machine"
        return f"Runs on {machine}. Open it on {machine}."
    if row.get("surface") == "cli":
        return "Runs in a terminal. ASB does not open CLI sessions."
    if row.get("provider") == "opencode":
        return "ASB cannot open OpenCode sessions. Open it in OpenCode."
    app = row.get("providerLabel") or APP_NAMES.get(row.get("provider"), "")
    return "ASB cannot open this session." + (f" Open it in {app}." if app else "")


def view_only_tone(row):
    """The Grey tone of a view-only row with no attention: "quiet" keeps the Working color, "rest" also dims the state."""
    if (not is_view_only(row) or row.get("unread") or row.get("questionAttention") or row.get("pending")
            or (row.get("limitResetsAtMs") or 0) > 0):
        return ""
    return "quiet" if row.get("state") == "working" else "rest"


# shortcut: a Comfortable column wider than about 370 px shows the … before its two lines are full; raise the limit if wide columns are common.
CARD_TITLE_CHARS = 85


def card_title(title):
    # Pango lays out the whole label text, also when the card shows only two lines; some titles are long prompts.
    text = " ".join(title.split()) or "Untitled session"
    return text if len(text) <= CARD_TITLE_CHARS else text[:CARD_TITLE_CHARS - 1].rstrip() + "…"


def ellipsis_cut(text, width, measure):
    """The text when it fits the width, else its longest start that fits with "…" after it, with no white space before the "…".
    measure(text) gives a width in the unit of width."""
    if measure(text) <= width:
        return text
    # shortcut: a cut never falls before a combining mark, a variation selector, or a joiner, but it can split other
    # grapheme clusters (some flags); use the Pango cursor positions when PyGObject reads their bit fields correctly.
    stops = [index for index in range(len(text)) if index == 0 or not unicodedata.combining(text[index])
             and text[index] not in "\u200d\ufe0e\ufe0f" and text[index - 1] != "\u200d"]
    low, high = 0, len(stops) - 1
    while low < high:
        middle = (low + high + 1) // 2
        if measure(text[:stops[middle]] + "…") <= width:
            low = middle
        else:
            high = middle - 1
    return text[:stops[low]].rstrip() + "…"


def short_home_path(path, home_dir):
    home = str(Path(home_dir))
    # A Windows home (a drive or UNC root) uses a backslash; in a Linux path a backslash is part of a file name.
    separator = "\\" if ntpath.splitdrive(home)[0] else "/"
    if path == home:
        return "~"
    if path.startswith(home.rstrip(separator) + separator):
        return "~" + path[len(home.rstrip(separator)):]
    return path


def failed_unread_note(row):
    """The note of an unread failed result: a Claude Code process that ended during a task says so."""
    return "The Claude Code process ended during a task. Not read yet." if row.get("processEnded") else "Failed. Not read yet."


def tooltip_model(row, now_ms, home_dir, error="", drawer_view=False):
    full_path = row.get("cwd") or row.get("projectName") or "No project folder"
    path = short_home_path(full_path, home_dir)
    state = row.get("state", "unknown")
    state = state if state in STATES else "unknown"
    state_text = state_word(row) + " · " + (working_duration(row, now_ms) or row_meta(row, now_ms).split(" · ")[1])
    provider = row.get("providerLabel") or APP_NAMES.get(row.get("provider"), "Unknown app")
    source_label, source_id = row.get("sourceLabel", ""), row.get("sourceId", "")
    app = provider + (" · " + source_label if source_label and source_label != provider else "")
    indicator = attention_indicator(row, True)
    # A drawer row has its unread note in each view, and its dot only where the row shows it.
    shape = "" if indicator in ("dot", "question") and row.get("drawer") and not row.get("unread") and not drawer_view else indicator
    note = ""
    if indicator == "question":
        note = "Waits for your permission." if (row.get("actionRequired") if row.get("drawer") and state == "waiting" else shows_action(row)) else "Asks a question. Open the chat to answer."
    elif indicator == "alert":
        note = "Usage limit stopped the task. Not read yet." if row.get("lastOutcome") == "limit" else failed_unread_note(row)
    elif indicator == "dot":
        source = row.get("pendingSource", "")
        dot_notes = {"manual-unread": "Marked unread in ASB.", "native-unread": "Unread in the original app.",
                     "observed-completion": "Finished. Not read yet.", "observed-failure": failed_unread_note(row)}
        if source in dot_notes:
            note = dot_notes[source]
            if row.get("retainedUnread") and ((source == "native-unread" and not row.get("nativeAttention"))
                                             or (source == "observed-completion" and not row.get("completionAttention"))):
                note = "Unread kept in ASB. Use Read to clear it."
        elif row.get("retainedUnread") and source:
            note = "Unread kept in ASB. Use Read to clear it."
        elif row.get("manualUnread"):
            note = "Marked unread in ASB."
        elif row.get("failedAttention"):
            note = failed_unread_note(row)
        elif row.get("nativeAttention"):
            note = "Unread in the original app."
        elif row.get("completionAttention"):
            note = "Finished. Not read yet."
        else:
            note = "Unread kept in ASB. Use Read to clear it."
    elif indicator == "stop":
        note = "The usage limit stopped this task." if row.get("lastOutcome") == "limit" else "You stopped this task."
    elif indicator == "discard":
        note = "Mark next result read: no dot when the next task ends." if row.get("state") == "idle" else "Mark read when done: no dot when this task ends."
    elif row.get("questionPending"):
        note = "A question is still open in the chat."
    elif state == "unknown":
        # An Unknown card says why, in the engine's words.
        note = row.get("reason", "")
    flags = " · ".join(text for key, text in (("pinned", "Pinned"), ("archived", "Archived"), ("drawer", "In the drawer")) if row.get(key))
    muted = mute_flag_text(row, now_ms)
    flags += (" · " if flags and muted else "") + muted
    if is_view_only(row):
        machine = row.get("machineName") or "another machine"
        where = " · ".join(([f"On {machine}"] if row.get("remote") else []) + (["CLI session"] if row.get("surface") == "cli" else []))
        flags += (" · " if flags else "") + where
        flags += f". Open it on {machine}." if row.get("remote") else ". Runs in a terminal. ASB does not open CLI sessions."
    elif not row.get("canOpen"):
        flags += (" · " if flags else "") + "No direct link"
        flags += ". " + no_open_title(row)
    source = "Profile: " + (source_label or source_id) if source_label or source_id else ""
    if source_label and source_id:
        source += " (" + source_id + ")"
    app_color = source_marker_color(row)
    if app_color:
        source += (". " if source else "") + "Profile color marker: " + app_color
    limit = ""
    if limit_left(row, now_ms):
        reset_at = time.localtime(row["limitResetsAtMs"] / 1000)
        reset = local_clock_text(row["limitResetsAtMs"])
        now_at = time.localtime((time.time() * 1000 if now_ms is None else now_ms) / 1000)
        day = "" if reset_at[:3] == now_at[:3] else " " + time.strftime("%A", reset_at)
        # A reset 6 to 7 days away has the weekday of today, so it also needs the date.
        if day and reset_at.tm_wday == now_at.tm_wday:
            day += f" {reset_at.tm_mday} " + time.strftime("%B", reset_at)
        limit = f"{source_label or provider} is out of usage. It resets{day} at {reset}."
    return {"path": path, "full_path": full_path, "title": row.get("title") or "Untitled session",
            "state": state, "state_text": state_text, "app": app, "app_color": app_color,
            "indicator": shape, "note": note, "flags": flags, "error": error,
            "reason": row.get("reason", ""), "source": source, "limit": limit}


def tooltip_description(model):
    return "\n".join(filter(None, (model["title"], model["full_path"], model["state_text"], model["app"],
                                  model["reason"], model["source"], model["limit"], model["note"] if model["note"] != model["reason"] else "",
                                  model["flags"], model["error"])))


def local_base_url(value):
    parsed = urlsplit(value)
    if parsed.scheme != "http" or parsed.hostname != "127.0.0.1" or not parsed.port \
            or parsed.username or parsed.password or parsed.path not in ("", "/") \
            or parsed.query or parsed.fragment:
        raise ValueError("Use the local ASB address: http://127.0.0.1:<port>.")
    return value.rstrip("/")


SOURCE_TOKEN = os.environ.get("ASB_SOURCE_TOKEN", "")


def group_fingerprint(value):
    return " ".join(value[index:index + 4] for index in range(0, len(value), 4))


PHONE_KINDS = {"lan": "Home network", "zerotier": "ZeroTier", "tailscale": "Tailscale"}
PHONE_OVERLAY_NOTE = "Install and join ZeroTier or Tailscale on this PC and the phone to use ASB away from home."


def phone_status_text(status):
    if status.get("running"):
        port = status.get("port", 4630)
        running = "Running at " + ", ".join(f"https://{item['address']}:{port} ({PHONE_KINDS.get(item['kind'], item['kind'])})"
                                            for item in status.get("listening", []))
        return "\n".join(filter(None, (running, status.get("error", ""))))
    if status.get("error"):
        return status["error"]
    if not status.get("enabled"):
        return "Phone access is off."
    return "Phone access is not running. Apply the settings to try again."


def phone_address_rows(addresses, selected=()):
    rows = [{"address": item["address"], "title": PHONE_KINDS[item["kind"]],
             "subtitle": item["address"] + ("" if item["kind"] == "lan" else " · Works away from home")}
            for item in addresses if item.get("kind") in PHONE_KINDS]
    # A saved address that is absent now (ZeroTier is off) stays, so Apply does not drop it.
    shown = {row["address"] for row in rows}
    return rows + [{"address": address, "title": "Not on this PC now",
                    "subtitle": address + " · ASB listens on it when it appears"}
                   for address in selected if address not in shown]


def phone_form_values(loaded, form, status):
    """The (enabled, port, checked addresses) to show after a status read. A form that differs from the last
    loaded values has unsaved edits, so it stays; otherwise the form follows the server."""
    server = (status.get("enabled", False), status.get("port", 4630), list(status.get("bindAddresses", [])))
    if loaded is None or form is None or (form[0], form[1], set(form[2])) == (loaded[0], loaded[1], set(loaded[2])):
        return server
    return form


def phone_address_note(addresses):
    kinds = {item.get("kind") for item in addresses}
    return " ".join(filter(None, ("" if addresses else "No private network address on this PC.",
                                  "" if kinds & {"zerotier", "tailscale"} else PHONE_OVERLAY_NOTE)))


def qr_matrix(uri):
    try:
        import qrcode
        import gi
        # The draw callback of the QR code needs PyGObject cairo support.
        gi.require_foreign("cairo")
    except ImportError:
        return None
    code = qrcode.QRCode(error_correction=qrcode.constants.ERROR_CORRECT_M, border=4)
    code.add_data(uri)
    code.make(fit=True)
    return code.get_matrix()


MACHINE_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,31}")
MACHINE_INTRO = ("Machines in a group show each other's sessions as view-only cards. "
                 "They connect over the addresses that you select in Phone.")
MACHINE_ALONE = "This machine is not in a group. Add a machine to make a group, or join the group of another machine."
MACHINE_OFF = "Network access is off. Machines connect over the same private addresses as phones."


def machine_status_text(member, now_ms=None):
    if member.get("isSelf"):
        return "This machine"
    if member.get("online"):
        return "Online"
    if not member.get("lastOkAtMs"):
        return "Offline"
    return "Offline · last seen " + row_meta({"updatedAtMs": member["lastOkAtMs"]}, now_ms).split(" · ", 1)[1]


def machine_addresses_text(member):
    return " · ".join(f"{item['address']} ({PHONE_KINDS.get(item['kind'], item['kind'])})" for item in member.get("addresses", []))


def machine_member_subtitle(member, now_ms=None):
    return "\n".join(filter(None, (f"{machine_status_text(member, now_ms)} · ID {member['machineId'][:8]}",
                                    machine_addresses_text(member))))


def machine_asb_relation(member, own):
    def version_key(value):
        match = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?", value or "")
        return (*map(int, match.group(1, 2, 3)), match[4] is None) if match else None
    current, baseline = version_key(member.get("asbVersion")), version_key(own.get("asbVersion"))
    if current is None or baseline is None:
        return ""
    if current != baseline:
        return ("older" if current < baseline else "newer") + " than this machine"
    build, own_build = member.get("asbBuild"), own.get("asbBuild")
    if not build or not own_build:
        return "same version as this machine"
    if build == own_build:
        return "same as this machine"
    at, own_at = member.get("asbBuildAtMs", 0), own.get("asbBuildAtMs", 0)
    return ("older" if at < own_at else "newer" if at > own_at else "other") + " build than this machine"


def machine_asb_line(member, own):
    version = member.get("asbVersion", "")
    if not version:
        return "ASB: not known while offline" if member.get("online") is False else "ASB: not known yet"
    line = "ASB " + version
    if member.get("asbBuild"):
        line += " · " + member["asbBuild"][:7]
    relation = "" if member.get("isSelf") else machine_asb_relation(member, own)
    return line + (" · " + relation if relation else "")


def machine_outdated(member, own, members, bridge):
    if any(app.get("state") == "update" for app in (bridge or {}).get("apps", [])):
        return True
    if member.get("isSelf"):
        return any(other.get("online") and not other.get("isSelf") and machine_asb_relation(other, own)
                   in ("newer than this machine", "newer build than this machine") for other in members)
    return machine_asb_relation(member, own) in ("older than this machine", "older build than this machine")


def machine_phones_text(phones):
    if not phones:
        return ""
    return ("Phones in the group: " + ", ".join(phone["name"] for phone in phones)
            + ". A phone paired on one machine works with all of them.")


def machines_view(group):
    on, grouped = bool(group.get("networkEnabled")), bool(group.get("groupId"))
    return {"off": not on, "grouped": grouped, "others": [member for member in group.get("members", []) if not member.get("isSelf")],
            "add": on, "join": on, "join_visible": not grouped, "leave_visible": grouped}


def machine_names_text(names):
    return names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]


def machine_confirm_body(others, removed=""):
    """The alert body for Remove (removed is the machine name) or Leave; others are the other active machine names."""
    if removed:
        stop = f"This PC and {machine_names_text(others)} stop" if others else "This PC stops"
        return (f"{removed} leaves the group. {stop} showing its sessions, and it stops showing theirs. "
                f"To join again, {removed} must reset its identity first.")
    return " ".join(filter(None, (f"This PC stops showing the sessions of {machine_names_text(others)}, and they stop showing its sessions."
                                  if others else "", "Phones that were paired on another machine stop working with this PC.")))


def join_link_summary(text):
    """The inviter name and fingerprint to compare, or None. The engine checks the rest of the link."""
    text = text.strip()
    if not text.startswith("asb://join?"):
        return None
    values = {}
    for part in text[len("asb://join?"):].split("&"):
        pieces = part.split("=")
        if len(pieces) != 2 or pieces[0] in values:
            return None
        values[pieces[0]] = unquote(pieces[1])
    if set(values) != set("vgapfcn") or values["v"] != "1" or not re.fullmatch(r"[a-f0-9]{64}", values["f"]) \
            or not MACHINE_NAME.fullmatch(values["n"]):
        return None
    return {"name": values["n"], "fingerprint": values["f"]}


def machine_invite_text(expires_at_ms):
    ends = time.strftime("%H:%M", time.localtime(expires_at_ms / 1000))
    return ("On the other machine, open Preferences > Machines, select Join a group, and paste this link. "
            f"The link works once and ends at {ends}.")


# Messages and Usage windows: names, colors, and formats that both windows share.
